  function capabilityPercent(c){const fields=[c?.legalName,c?.registrationCountry,c?.yearsOperating,c?.turnoverBand,(c?.sectors||[]).length,(c?.countries||[]).length,(c?.donorExperience||[]).length,(c?.licences||[]).length,c?.referenceCount];return Math.round(fields.filter(Boolean).length/fields.length*100)}
  async function loadCapability(){if(!state.session)return;try{const data=await api('/api/me/capability'),c=data.capability||{};$('capabilityLegalName').value=c.legalName||'';$('capabilityRegistrationCountry').value=c.registrationCountry||'';$('capabilityRegistrationNumber').value=c.registrationNumber||'';$('capabilityYears').value=c.yearsOperating??'';$('capabilityTurnover').value=c.turnoverBand||'';$('capabilitySectors').value=(c.sectors||[]).join(', ');$('capabilityCountries').value=(c.countries||[]).join(', ');$('capabilityDonors').value=(c.donorExperience||[]).join(', ');$('capabilityLicences').value=(c.licences||[]).join(', ');$('capabilityReferences').value=c.referenceCount||'';$('capabilityProfileType').value=c.profileType||$('profileType').value||'individual';$('capabilityRecruit').checked=c.canRecruitSpecialists===true;$('capabilityCompleteness').textContent=`${capabilityPercent(c)}%`;}catch(e){$('capabilityMessage').textContent=e.message}}
  async function saveCapability(event){event.preventDefault();if(!requireAuth())return;const msg=$('capabilityMessage');msg.textContent='Saving eligibility context…';try{const payload={legalName:$('capabilityLegalName').value.trim(),registrationCountry:$('capabilityRegistrationCountry').value.trim(),registrationNumber:$('capabilityRegistrationNumber').value.trim(),yearsOperating:$('capabilityYears').value,turnoverBand:$('capabilityTurnover').value.trim(),sectors:list($('capabilitySectors').value),countries:list($('capabilityCountries').value),donorExperience:list($('capabilityDonors').value),licences:list($('capabilityLicences').value),referenceCount:Number($('capabilityReferences').value||0),profileType:$('capabilityProfileType').value,canRecruitSpecialists:$('capabilityRecruit').checked};const data=await api('/api/me/capability',{method:'PUT',body:JSON.stringify(payload)});$('capabilityCompleteness').textContent=`${capabilityPercent(data.capability)}%`;msg.textContent='Saved. Radar will re-score current opportunities with these eligibility facts.';$('profileType').value=payload.profileType;$('profileRecruitSpecialists').checked=payload.canRecruitSpecialists;toast('Capability profile updated.');await loadOpportunities();}catch(e){msg.textContent=e.message}}
  async function loadBriefing(){if(!requireAuth())return;try{const data=await api('/api/me/briefing'),p=data.preferences||{};$('briefEnabled').checked=p.dailyBriefEnabled===true;$('briefHour').value=String(p.deliveryHour||8);$('briefTimezone').value=p.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'Africa/Kampala';$('briefMinFit').value=String(p.minFitScore??60);$('briefMinDays').value=String(p.minDaysToDeadline??7);$('briefEmail').checked=p.emailBrief!==false;$('briefWhatsapp').checked=p.whatsappBrief===true;$('briefPhone').value=state.session?.user?.phone||'';$('briefingMessage').textContent=data.alert?.lastSent?`Last brief sent ${fmtDate(data.alert.lastSent)}.`:'Your brief has not been sent yet.';}catch(e){toast(e.message)}}
